package com.yeyamo_mobile.api.payment_service.infrastructure.messaging;
import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import java.util.UUID;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.payment_service.application.PaymentApplicationService;
class PaymentCommandConsumerTests{
 @Test void consumesBookingAuthorizationCommandOnlyOnce()throws Exception{var service=mock(PaymentApplicationService.class);var processed=mock(ProcessedEventRepository.class);UUID event=UUID.randomUUID(),booking=UUID.randomUUID(),saga=UUID.randomUUID();when(processed.existsById(event)).thenReturn(false,true);String raw="{\"eventId\":\""+event+"\",\"eventType\":\"payment.authorization.requested\",\"eventVersion\":1,\"correlationId\":\"corr\",\"payload\":{\"sagaId\":\""+saga+"\",\"bookingId\":\""+booking+"\",\"userId\":\"user-1\",\"amount\":20.00,\"currency\":\"EUR\",\"idempotencyKey\":\"booking:key\"}}";var consumer=new PaymentCommandConsumer(new ObjectMapper(),service,processed);consumer.consume(raw);consumer.consume(raw);verify(service).authorize(argThat(c->c.bookingId().equals(booking)&&c.amount().compareTo(new java.math.BigDecimal("20.00"))==0));verify(processed).save(any());}
}
